package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A client the user tracks: a name and an email. Maps the {@code clients} table (Flyway
 * V1__clients.sql); the id is IDENTITY-generated on create.
 */
@Entity
@Table(name = "clients")
public class Client {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private String email;

    // Whether the client has been archived (tucked away): an archived client is retained but drops
    // off the list and the search. New clients start not-archived (the column default,
    // V19__client_archived.sql).
    @Column(nullable = false)
    private boolean archived;

    protected Client() {
    }

    public Client(String name, String email) {
        this.name = name;
        this.email = email;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public boolean isArchived() {
        return archived;
    }

    /** Tuck this client away so it drops off the list and the search while the row is kept. */
    public void archive() {
        this.archived = true;
    }

    /** Correct this client's details — its name and email — in place. */
    public void update(String name, String email) {
        this.name = name;
        this.email = email;
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/clients/sorted?sort=&lt;key&gt; — the clients list in a chosen order, for the sort control
 * on the clients page. Archived (tucked-away) clients are excluded, exactly as on the plain list
 * {@link ListClients}. The {@code sort} key chooses the order:
 * <ul>
 *   <li>{@code outstanding} — most-owed-first. Each client's outstanding balance is DERIVED on the
